using System;using System.IO;using System.Text;using System.Security.Cryptography;using System.Web.Script.Serialization;
class ProviderProtection{
 static int Main(){byte[] bytes=null,clear=null;try{Console.InputEncoding=new UTF8Encoding(false);Console.OutputEncoding=new UTF8Encoding(false);string line=Console.In.ReadToEnd();if(line.Length>65536)throw new Exception();var j=new JavaScriptSerializer();var r=j.Deserialize<System.Collections.Generic.Dictionary<string,string>>(line);bytes=Convert.FromBase64String(r["data"]);if(bytes.Length>32768)throw new Exception();clear=r["mode"]=="open"?ProtectedData.Unprotect(bytes,null,DataProtectionScope.CurrentUser):r["mode"]=="seal"?ProtectedData.Protect(bytes,null,DataProtectionScope.CurrentUser):null;if(clear==null)throw new Exception();Console.Write(j.Serialize(new{data=Convert.ToBase64String(clear)}));return 0;}catch{Console.Write("{\"error\":\"Device protection unavailable\"}");return 1;}finally{if(bytes!=null)Array.Clear(bytes,0,bytes.Length);if(clear!=null)Array.Clear(clear,0,clear.Length);}}
}
